package com.javasmyths.highguard;
import com.fasterxml.jackson.databind.*;import com.javasmyths.highguard.book2.*;import java.util.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
public class Book2Import {
 public static Design convert(byte[] bytes)throws Exception{
  if(bytes.length==0||bytes.length>1000000)throw new IllegalArgumentException("Choose a Book 2 JSON export under 1 MB.");ObjectMapper mapper=new ObjectMapper();JsonNode root=mapper.readTree(bytes);if(!root.isObject()||!root.path("design").isObject()||root.path("schemaVersion").asInt()!=1||root.has("ruleset"))throw new IllegalArgumentException("This is not a supported Book 2 ship export. Use Download JSON in the original ship builder.");
  ShipDesign old=mapper.treeToValue(root.get("design"),ShipDesign.class);Book2Rules.Report before=Book2Rules.calculate(old);if(!before.valid)throw new IllegalArgumentException("The source Book 2 design is invalid: "+String.join(" ",before.errors));Design d=new Design();d.name=old.name+" · High Guard";if(d.name.length()>120)d.name=d.name.substring(0,120);d.shipClass="Book 2 conversion";d.type="AN";d.hull=old.hull;d.jump=before.jump;d.maneuver=before.maneuver;d.power=before.power;d.tl=Math.max(12,new int[]{0,9,11,12,13,14,15}[d.jump]);d.configuration=old.streamlined?1:4;d.computer=old.computer;d.rooms=old.staterooms;d.lowBerths=old.lowBerths;d.emergencyBerths=old.emergencyBerths;d.passengers=old.highPassengers+old.middlePassengers;d.lowPassengers=old.lowBerths;d.military=false;d.fuel=-1;d.cargo=before.cargo;d.repeatClass=false;d.navalArchitect=false;d.batteries.clear();d.craft.clear();
  int[] counts={old.beamLasers,old.pulseLasers,old.missileRacks,old.sandcasters};String[] weapons={"beam","pulse","missile","sand"};int originalMounts=old.singleTurrets+old.doubleTurrets+old.tripleTurrets;for(int i=0;i<counts.length;i++)if(counts[i]>0){int n=counts[i]%3==0?3:counts[i]%2==0?2:1;d.batteries.add(new Design.Battery(weapons[i],counts[i]/n,n,1));}
  for(Map.Entry<String,Integer> e:old.vehicles.entrySet()){Book2Rules.Vehicle v=Book2Rules.VEHICLES.get(e.getKey());if(v!=null&&e.getValue()>0){Design.Craft c=new Design.Craft(v.name,v.tons,v.credits/1e6,e.getValue(),v.smallCraft?1:1);if(!v.smallCraft){c.kind="vehicle";if(e.getKey().equals("atvTracked"))c.mcr=.07;}d.craft.add(c);}}
  d.otherMcr=old.extraSoftwareCredits/1e6;d.sourceName=old.name;d.sourceJson=new String(bytes,StandardCharsets.UTF_8);byte[] digest=MessageDigest.getInstance("SHA-256").digest(bytes);StringBuilder hash=new StringBuilder();for(byte b:digest)hash.append(String.format("%02x",b));d.sourceHash=hash.toString();
  d.importNotes.add("Original Book 2 ship and its save file are preserved. This is a new High Guard design, not a replacement.");d.importNotes.add("Target TL "+d.tl+" is an initial assumption; choose your actual shipyard TL. Configuration "+d.configuration+" interprets the source streamlining choice.");d.importNotes.add("Performance retained: J"+d.jump+", "+d.maneuver+"G, P"+d.power+". Custom High Guard drives replace lettered Book 2 machinery; their tonnage and prices are recalculated.");d.importNotes.add("Source fuel "+HighGuardRules.fmt(before.fuel)+"t is replaced by the High Guard one-jump + four-week minimum; explicit source cargo "+HighGuardRules.fmt(before.cargo)+"t remains a target and may no longer fit.");
  d.importNotes.add("Source price MCr"+HighGuardRules.fmt(before.shipPrice/1e6)+" is historical only. High Guard prices, crew and quarters are recalculated. Standard-hull and standard-plan discounts do not transfer.");
  if(Arrays.stream(counts).sum()>0)d.importNotes.add("Source had "+originalMounts+" turret mounts. Imported weapons are regrouped into homogeneous High Guard turrets, each a battery. Review mounts, grouping and any additional hardpoints required; source mixed-turret placement is not represented in the Book 2 export.");
  if(!d.craft.isEmpty())d.importNotes.add("Carried craft retain their listed Book 2 purchase values and identities. High Guard hangar allowances and fees are added; these craft are carried references, not certified new High Guard small-craft designs. Cutter modules are recorded as equipment.");
  if(old.crew>0)d.importNotes.add("Source assigned crew: "+old.crew+". High Guard calculates required positions; add extra assigned crew where needed. Source double-role or double-occupancy approvals need a fresh review.");
  d.importReviewed=false;return d;
 }
}
